create table if not exists public.phone_bill_data(user_id uuid primary key references auth.users(id) on delete cascade,data jsonb not null default '{"version":2,"people":[],"lines":[],"transactions":[]}'::jsonb,updated_at timestamptz not null default now());alter table public.phone_bill_data enable row level security;grant select,insert,update,delete on public.phone_bill_data to authenticated;create policy "Users can read own phone bill data" on public.phone_bill_data for select to authenticated using(auth.uid()=user_id);create policy "Users can insert own phone bill data" on public.phone_bill_data for insert to authenticated with check(auth.uid()=user_id);create policy "Users can update own phone bill data" on public.phone_bill_data for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "Users can delete own phone bill data" on public.phone_bill_data for delete to authenticated using(auth.uid()=user_id);